import json
import sys
from datetime import datetime, timezone, timedelta


def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 string into a datetime in UTC."""
    if s is None:
        return None
    # Handle 'Z' suffix
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    # Must be offset-aware (has tzinfo with offset)
    if dt.tzinfo is None or dt.utcoffset() is None:
        return None  # naive or no offset → skip
    return dt.astimezone(timezone.utc)


def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = parse_offset_aware(data["as_of"])
    if as_of is None:
        print(json.dumps([]))
        return

    results = []
    for r in data.get("reminders", []):
        # Skip completed reminders
        if r.get("completed", False):
            continue
        due_raw = r.get("due")
        # Skip missing, null, or naive due values
        if due_raw is None:
            continue
        due_dt = parse_offset_aware(due_raw)
        if due_dt is None:
            continue
        # Include only if due AT OR BEFORE as_of
        if due_dt <= as_of:
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": due_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
            })

    # Sort by actual due instant (UTC), then by id
    results.sort(key=lambda x: (x["due_utc"], x["id"]))
    print(json.dumps(results))


if __name__ == "__main__":
    main()
